1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Step = {
8	  op: string;
9	  items: Item[];
10	};
11	
12	export type Customer = {
13	  yearsWithMHPCO: number;
14	};
15	
16	export type Scenario = {
17	  customer: Customer;
18	  steps: Step[];
19	};
20	
21	export type Result = {
22	  premium: number;
23	};
24	
25	export type ScenarioOutcome = {
26	  results: Result[];
27	};
28	
29	const PROCESSING_FEE = 5;
30	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	// Percentages are applied as the exact fraction `amount * percent / 100`
40	// rather than via a float factor such as `amount * 0.1`, which drifts.
41	const percentOf = (percent: number, amount: number): number =>
42	  (amount * percent) / 100;
43	
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	const CURSE_SURCHARGE_PERCENT = 50;
46	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	
49	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
50	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
51	
52	const LOYALTY_DISCOUNT_PERCENT = 20;
53	const LOYALTY_YEARS_THRESHOLD = 2;
54	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
55	
56	// Discounts attached to the policy are percentages of the policy base premium,
57	// so they can be summed as percentages and applied in one go.
58	const policyDiscountsOn = (
59	  policyBasePremium: number,
60	  customer: Customer,
61	  quotesAlreadyProcessed: number,
62	): number => {
63	  const loyaltyPercent =
64	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
65	      ? LOYALTY_DISCOUNT_PERCENT
66	      : 0;
67	  const followUpPercent =
68	    quotesAlreadyProcessed > 0 ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
69	  return percentOf(loyaltyPercent + followUpPercent, policyBasePremium);
70	};
71	
72	// Surcharges attached to a single item are a percentage of that item's own
73	// base premium from the price list (never of the policy base premium).
74	const surchargeForItem = (item: Item): number => {
75	  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
76	  const highEnchantmentPercent =
77	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
78	      ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
79	      : 0;
80	  return percentOf(
81	    cursePercent + highEnchantmentPercent,
82	    BASE_PREMIUM_BY_TYPE[item.type],
83	  );
84	};
85	
86	const itemSurchargesOf = (items: Item[]): number =>
87	  items.reduce((total, item) => total + surchargeForItem(item), 0);
88	
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
92	
93	const countByType = (items: Item[]): Map<string, number> => {
94	  const counts = new Map<string, number>();
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	  return counts;
99	};
100	
101	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
102	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
103	// items never form a block.
104	const basePremiumForAlikeItems = (type: string, count: number): number =>
105	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
106	    ? BLOCK_BASE_PREMIUM
107	    : count * BASE_PREMIUM_BY_TYPE[type];
108	
109	const policyBasePremiumOf = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
112	    0,
113	  );
114	
115	// The processing fee is added after every percentage modifier, so it is never
116	// itself discounted. Only the final premium is rounded, and always up.
117	const premiumFor = (
118	  items: Item[],
119	  customer: Customer,
120	  quotesAlreadyProcessed: number,
121	): number => {
122	  const policyBasePremium = policyBasePremiumOf(items);
123	  const surcharges =
124	    itemSurchargesOf(items) + firstInsuranceSurchargeOn(policyBasePremium);
125	  const discounts = policyDiscountsOn(
126	    policyBasePremium,
127	    customer,
128	    quotesAlreadyProcessed,
129	  );
130	  return Math.ceil(
131	    policyBasePremium + surcharges - discounts + PROCESSING_FEE,
132	  );
133	};
134	
135	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
136	  results: scenario.steps.map((step, quotesAlreadyProcessed) => ({
137	    premium: premiumFor(step.items, scenario.customer, quotesAlreadyProcessed),
138	  })),
139	});
