const claimResultFor = (step: Step): ClaimResult => ({
  payout: 0,
  remainingCap: 0,
});

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, quotesAlreadyProcessed) =>
    step.op === "claim"
      ? claimResultFor(step)
      : {
          premium: premiumFor(
            step.items ?? [],
            scenario.customer,
            quotesAlreadyProcessed,
          ),
        },
  ),
});
